+		}
+		if out == nil {
+			return trace.BadParameter("DynamoDB batch write returned no result during FieldsMap migration")
+		}
+		requests = out.UnprocessedItems[table]
+		if len(requests) == 0 {
+			return nil
+		}
+		select {
+		case <-time.After(backoff):
+		case <-ctx.Done():
+			return trace.Wrap(ctx.Err())
+		}
+		if backoff < 5*time.Second {
+			backoff *= 2
+		}
+	}
+	return nil
