					}
					if err := writeFieldsMapBatch(workerCtx, client, table, batch); err != nil {
						errOnce.Do(func() { firstErr = err; cancel() })
						return
					}
				}
			}
		}()
	}
	workers.Wait()
	if firstErr != nil {
		return trace.Wrap(firstErr)
	}
	return trace.Wrap(ctx.Err())
}

